const node = await figma.getNodeByIdAsync('2:3');
if (!node) return { deleted: false, reason: 'node 2:3 not found' };
const tagged = node.type === 'SECTION' && node.getSharedPluginDataKeys('productowner').includes('Start a return');
if (node.type !== 'SECTION' || node.name !== 'Start a return' || !tagged) {
  return { deleted: false, reason: 'node 2:3 is not the tagged Start a return section', type: node.type, name: node.name, tagged };
}
const removed = { id: node.id, name: node.name, x: node.x, y: node.y, width: node.width, height: node.height };
node.remove();
const stillThere = await figma.getNodeByIdAsync('2:3');
return { deleted: !stillThere, removed, remainingTopLevel: figma.currentPage.children.map((n) => ({ id: n.id, type: n.type, name: n.name })) };

